package fr.formation.clean.application.usecase;import fr.formation.clean.application.boundary.*;import java.util.UUID;public final class CancelReservationInteractor implements CancelReservationInputBoundary{private final ReservationGateway reservations;public CancelReservationInteractor(ReservationGateway reservations){this.reservations=reservations;}public void execute(UUID id){var r=reservations.findById(id).orElseThrow(()->new UseCaseException("Reservation not found"));reservations.save(r.cancel());}}
